__attribute__((weak)) void rLayout::filePath2LayoutID(rLayout::TYPE& lotType, nLayout::stLayoutID& layoutID, MT_CTSTR filePath) {
    MtString fileTitle;
    {
        MtFilePath fp(filePath);
        fileTitle = fp.getFileTitle();
    }
    for (u32 i = 0; i < 5; i++) {
        if (strstr(fileTitle.ptr(), typeKeyWord[i]) != nullptr) {
            lotType = static_cast<rLayout::TYPE>(i);
            layoutID.mGroup = gLot::getS32_Key(fileTitle, typeKeyWord[i], false);
            break;
        }
    }
    layoutID.mArea = gLot::getS32_Key(fileTitle, "st", false);
}

__attribute__((weak)) void rLayout::filePath2SplitID(nLayout::stSplitID& splitID, MT_CTSTR filePath) {
    MtString fileTitle;
    {
        MtFilePath fp(filePath);
        fileTitle = fp.getFileTitle();
    }
    splitID.mSplitZ = gLot::getS32_Key(fileTitle, "_", false);
    splitID.mSplitX = gLot::getS32_Key(fileTitle, "m", false);
}

